function browserCountryCode(){try{const langs=[navigator.language,...(navigator.languages||[])];for(const lang of langs){const match=String(lang||"").match(/[-_]([A-Za-z]{2})$/);if(match)return match[1].toUpperCase()}return null}catch{return null}}function liveRole(accountRole,isMember){const role=String(accountRole||"").trim().toLowerCase();if(!isMember||role==="guest")return"guest";if(["creator","host","podcaster"].includes(role))return"creator";return"listener"}
let liveCountsRefreshInFlight=null,liveCountsLastRefreshAt=0,liveCountsLastData=null;
async function renderLiveCounts(){
 const now=Date.now();
 if(liveCountsRefreshInFlight)return liveCountsRefreshInFlight;
 if(liveCountsLastData&&now-liveCountsLastRefreshAt<4000){
  applyLiveCountValues(liveCountsLastData);return liveCountsLastData;
 }
 liveCountsRefreshInFlight=(async()=>{
  try{
   const{data,error}=await sb.rpc("podcasting_get_live_counts");
   if(error)throw error;
   const counts={creator:Number(data?.creator||0),listener:Number(data?.listener||0),guest:Number(data?.guest||0)};
   counts.total=Number(data?.total??(counts.creator+counts.listener+counts.guest));
   liveCountsLastData=counts;liveCountsLastRefreshAt=Date.now();applyLiveCountValues(counts);return counts;
  }catch(error){console.warn("Live audience counts could not be refreshed:",error?.message||error);return liveCountsLastData}
  finally{liveCountsRefreshInFlight=null}
 })();
 return liveCountsRefreshInFlight;
}
function applyLiveCountValues(counts){
 const c=$("#liveCreatorCount"),l=$("#liveListenerCount"),g=$("#liveGuestCount"),allOnline=$("#liveTotalCount");
 if(c)c.textContent=counts.creator.toLocaleString();if(l)l.textContent=counts.listener.toLocaleString();if(g)g.textContent=counts.guest.toLocaleString();if(allOnline)allOnline.textContent=counts.total.toLocaleString();
 const ac=$("#adminLiveCreatorCount"),al=$("#adminLiveListenerCount"),ag=$("#adminLiveGuestCount"),at=$("#adminLiveTotal");
 if(ac)ac.textContent=counts.creator.toLocaleString();if(al)al.textContent=counts.listener.toLocaleString();if(ag)ag.textContent=counts.guest.toLocaleString();if(at)at.textContent=counts.total.toLocaleString();
 livePresenceCounts={creator:counts.creator,listener:counts.listener,guest:counts.guest};
 if($("#adminPeakConcurrent")&&livePresenceSubscribed)refreshAdminLivePeak();
}
let livePeakRefreshAttempt=0;
async function refreshAdminLivePeak(){
 const now=Date.now();if(now-livePeakRefreshAttempt<20000)return;
 livePeakRefreshAttempt=now;
 try{
  const{data,error}=await sb.rpc("podcasting_admin_get_live_peak");
  if(error)throw error;
  const peak=$("#adminPeakConcurrent"),when=$("#adminPeakAt"),status=$("#adminPeakStatus");
  if(peak)peak.textContent=Number(data?.peak_simultaneous||0).toLocaleString();
  if(when)when.textContent=data?.peak_recorded_at?"Recorded "+new Date(data.peak_recorded_at).toLocaleString():"Waiting for first peak";
  if(status)status.textContent="24/7 TRACKING";
 }catch(error){console.warn("24/7 live peak could not be refreshed:",error?.message||error);const status=$("#adminPeakStatus");if(status)status.textContent="RETRYING"}
}
async function recordDailyVisitor(){
 try{
  const visitorKey=liveVisitorId();if(!visitorKey)return;
  const visitDay=new Date().toISOString().slice(0,10),marker="crp_visitor_recorded_"+visitDay;
  try{if(localStorage.getItem(marker)===visitorKey)return}catch{}
  const{error}=await sb.from("podcasting_visitor_events").insert({visitor_key:visitorKey,visit_day:visitDay,user_id:livePresenceUserId,page_path:location.pathname||"/"});
  if(error&&error.code!=="23505")throw error;
  try{localStorage.setItem(marker,visitorKey)}catch{}
 }catch(error){console.warn("Daily visitor analytics could not be recorded:",error?.message||error)}
}
async function syncLivePresence(user){
 const version=++livePresenceSyncVersion;
 try{
  if(arguments.length===0){const result=await sb.auth.getUser();user=result.data?.user||null}
  if(version!==livePresenceSyncVersion)return;
  livePresenceUserId=user?.id||null;
  let accountRole="",isMember=false;
  if(livePresenceUserId){
   const{data,error}=await sb.from("members").select("role").eq("user_id",livePresenceUserId).maybeSingle();
   if(version!==livePresenceSyncVersion)return;
   if(error){console.warn("Could not resolve member role for live presence:",error.message);isMember=true;accountRole="Listener"}
   else{isMember=!!data;accountRole=data?.role||""}
  }
  livePresenceRole=liveRole(accountRole,isMember);
  const touchNow=Date.now();if(touchNow-livePresenceLastTouchAt>=25000){livePresenceLastTouchAt=touchNow;try{const{error}=await sb.rpc("podcasting_touch_live_presence",{p_session_id:getLivePresenceSessionId(),p_role:livePresenceRole,p_page_path:location.pathname||"/",p_country_code:browserCountryCode()});if(error)throw error}catch(error){livePresenceLastTouchAt=0;console.warn("24/7 audience heartbeat could not be recorded:",error?.message||error)}}if(touchNow-(Number(window.__crpGeoLookupAt)||0)>=21600000){const geoSession=getLivePresenceSessionId();let geoDue=true;try{const marker="crp_geo_lookup_"+geoSession,last=Number(localStorage.getItem(marker)||0);geoDue=!last||touchNow-last>=21600000;if(geoDue)localStorage.setItem(marker,String(touchNow))}catch{}if(geoDue){window.__crpGeoLookupAt=touchNow;try{const{data:geoData,error:geoError}=await sb.functions.invoke("podcasting-live-visitor-geolocation",{body:{session_id:geoSession}});if(geoError||geoData?.ok!==true){try{localStorage.removeItem("crp_geo_lookup_"+geoSession)}catch{}window.__crpGeoLookupAt=0;console.warn("Approximate visitor geolocation unavailable:",geoError?.message||geoData?.reason||"unavailable")}}catch(geoError){try{localStorage.removeItem("crp_geo_lookup_"+geoSession)}catch{}window.__crpGeoLookupAt=0;console.warn("Approximate visitor geolocation unavailable:",geoError?.message||geoError)}}}
  await recordDailyVisitor();
  if(version!==livePresenceSyncVersion)return;
  await renderLiveCounts();
 }catch(error){if(version===livePresenceSyncVersion)console.warn("Live presence update failed:",error)}
}
function startLivePresence(){
 const nav=$("#liveNetworkCounts");if(!nav||!sb.channel||livePresenceChannel)return;
 const key=window.crypto?.randomUUID?.()||("tab-"+Date.now()+"-"+Math.random().toString(36).slice(2));
 livePresenceChannel=sb.channel("crowrules-podcasting-live-network",{config:{presence:{key}}})
 .on("presence",{event:"sync"},renderLiveCounts)
 .on("presence",{event:"join"},renderLiveCounts)
 .on("presence",{event:"leave"},renderLiveCounts);
 if(!livePresenceHeartbeat)livePresenceHeartbeat=setInterval(()=>{syncLivePresence();renderLiveCounts()},30000);if(!window.__crpLiveCountsPoll){window.__crpLiveCountsPoll=setInterval(renderLiveCounts,10000);renderLiveCounts();}if(!window.__crpPresenceVisibilityBound){window.__crpPresenceVisibilityBound=true;document.addEventListener("visibilitychange",()=>{if(!document.hidden){syncLivePresence();renderLiveCounts()}});window.addEventListener("online",()=>{const status=$("#liveNetworkStatus");if(status)status.textContent="RECONNECTING";syncLivePresence();renderLiveCounts()});window.addEventListener("offline",()=>{const status=$("#liveNetworkStatus");if(status)status.textContent="OFFLINE";const admin=$("#adminLiveStatus");if(admin)admin.textContent="OFFLINE"});}
 livePresenceChannel.subscribe(status=>{
  const label=$("#liveNetworkStatus"),adminLabel=$("#adminLiveStatus");
  if(status==="SUBSCRIBED"){
   livePresenceSubscribed=true;
   if(label)label.textContent="LIVE";if(adminLabel)adminLabel.textContent="LIVE";
   syncLivePresence();
   renderLiveCounts();
  }else if(status==="CHANNEL_ERROR"||status==="TIMED_OUT"||status==="CLOSED"){
   livePresenceSubscribed=false;
   if(label)label.textContent="RECONNECTING";if(adminLabel)adminLabel.textContent="RECONNECTING";
   renderLiveCounts();
  }
 });
}
function updateLivePresenceRole(){syncLivePresence()}
