 const totalShowsCounter=$("#homeTotalShowsCount");
 const latestShowsContainer=$("#homeLatestShows");
 if(totalShowsCounter||latestShowsContainer){
  let homeShowsRefreshInProgress=false;
  const refreshHomeLatestShows=async()=>{
   if(homeShowsRefreshInProgress)return;
   homeShowsRefreshInProgress=true;
   try{
    const requests=[];
    if(totalShowsCounter)requests.push(sb.from("podcasts").select("id",{count:"exact",head:true}).eq("status","published"));
    if(latestShowsContainer)requests.push(sb.from("podcasts").select("id,title,category,description,artwork_url,created_at").eq("status","published").order("created_at",{ascending:false,nullsFirst:false}).limit(3));
    const results=await Promise.all(requests);
    let resultIndex=0;
    if(totalShowsCounter){
     const countResult=results[resultIndex++];
     if(countResult.error)throw countResult.error;
     totalShowsCounter.textContent=Number(countResult.count||0).toLocaleString();
    }
    if(latestShowsContainer){
     const showResult=results[resultIndex++];
     if(showResult.error)throw showResult.error;
     const latestShows=showResult.data||[];
     if(!latestShows.length){
      latestShowsContainer.innerHTML='<div class="home-latest-loading">New shows are on the way. Be among the first to publish yours.</div>';
     }else{
      latestShowsContainer.innerHTML=latestShows.map((show,index)=>{
       const title=esc(show.title||"Untitled Show"),category=esc(show.category||"Podcast"),description=esc((show.description||"Discover this voice from the CrowRules Podcasting network.").trim());
       const artwork=show.artwork_url?'<img src="'+esc(show.artwork_url)+'" alt="'+title+' artwork" loading="lazy">':'<div class="home-latest-art-placeholder">CR</div>';
       const date=show.created_at?new Intl.DateTimeFormat(undefined,{month:"short",day:"numeric"}).format(new Date(show.created_at)):"Recently published";
       const showUrl=SITE_BASE+'show.html?id='+encodeURIComponent(show.id);
       return '<article class="home-latest-show-card"><a class="home-latest-show-art" href="'+showUrl+'">'+artwork+'<span>0'+(index+1)+'</span></a><div class="home-latest-show-info"><span class="home-latest-category">'+category+'</span><h3><a href="'+showUrl+'">'+title+'</a></h3><p>'+description+'</p><div class="home-latest-show-bottom"><small>'+esc(date)+'</small><a href="'+showUrl+'">Explore show →</a></div></div></article>';
      }).join("");
     }
    }
   }catch(error){
    console.warn("Homepage published shows could not be refreshed:",error);
    if(latestShowsContainer&&!latestShowsContainer.dataset.loaded)latestShowsContainer.innerHTML='<div class="home-latest-loading">The latest shows will be back shortly. Explore the full directory in the meantime.</div>';
   }finally{
    homeShowsRefreshInProgress=false;
    if(latestShowsContainer)latestShowsContainer.dataset.loaded="true";
   }
  };
  refreshHomeLatestShows();
  // Realtime updates move newly created or newly published shows into the spotlight without a reload.
  const homeShowsRealtime=sb.channel("homepage-latest-published-shows")
   .on("postgres_changes",{event:"*",schema:"public",table:"podcasts"},payload=>{
    const changed=payload.new||payload.old||{};
    if(payload.eventType==="DELETE"||changed.status==="published"||payload.old?.status==="published")refreshHomeLatestShows();
   })
   .subscribe(status=>{
    if(status==="CHANNEL_ERROR"||status==="TIMED_OUT")console.warn("Homepage show realtime is unavailable; periodic refresh remains active.");
   });
  // Fallback refresh keeps the homepage current if Realtime is not enabled for public.podcasts.
  window.setInterval(refreshHomeLatestShows,60000);
 }
 const holidayNthWeekday=(year,month,weekday,nth)=>{const first=new Date(year,month,1),offset=(weekday-first.getDay()+7)%7;return new Date(year,month,1+offset+(nth-1)*7)};
 const holidayLastWeekday=(year,month,weekday)=>{const last=new Date(year,month+1,0),offset=(last.getDay()-weekday+7)%7;return new Date(year,month,last.getDate()-offset)};
 const holidayEaster=(year)=>{const a=year%19,b=Math.floor(year/100),c=year%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),month=Math.floor((h+l-7*m+114)/31)-1,day=(h+l-7*m+114)%31+1;return new Date(year,month,day)};
 const holidaysForYear=year=>{const easter=holidayEaster(year);return [
  {name:"New Year’s Day",emoji:"🎉",date:new Date(year,0,1)},
  {name:"Valentine’s Day",emoji:"❤️",date:new Date(year,1,14)},
  {name:"Easter Sunday",emoji:"🐣",date:easter},
  {name:"Mother’s Day",emoji:"💐",date:holidayNthWeekday(year,4,0,2)},
  {name:"Father’s Day",emoji:"👔",date:holidayNthWeekday(year,5,0,3)},
  {name:"Independence Day",emoji:"🎆",date:new Date(year,6,4)},
  {name:"Labor Day",emoji:"🇺🇸",date:holidayNthWeekday(year,8,1,1)},
  {name:"Halloween",emoji:"🎃",date:new Date(year,9,31)},
  {name:"Thanksgiving",emoji:"🦃",date:holidayNthWeekday(year,10,4,4)},
  {name:"Christmas Day",emoji:"🎄",date:new Date(year,11,25)},
  {name:"New Year’s Eve",emoji:"✨",date:new Date(year,11,31)}
 ]};
 const holidayCountdownSlots=[
  {emoji:$("#nextHolidayEmoji"),name:$("#nextHolidayName"),date:$("#nextHolidayDate"),days:$("#nextHolidayDays"),hours:$("#nextHolidayHours"),minutes:$("#nextHolidayMinutes"),seconds:$("#nextHolidaySeconds")},
  {emoji:$("#secondHolidayEmoji"),name:$("#secondHolidayName"),date:$("#secondHolidayDate"),days:$("#secondHolidayDays"),hours:$("#secondHolidayHours"),minutes:$("#secondHolidayMinutes"),seconds:$("#secondHolidaySeconds")}
 ];
 if(holidayCountdownSlots.every(slot=>slot.days&&slot.hours&&slot.minutes&&slot.seconds)){
  let activeHolidayKeys="";
  const updateUpcomingHolidays=()=>{
   const now=new Date();
   const upcoming=holidaysForYear(now.getFullYear()).concat(holidaysForYear(now.getFullYear()+1),holidaysForYear(now.getFullYear()+2))
    .map(item=>({...item,target:new Date(item.date.getFullYear(),item.date.getMonth(),item.date.getDate()+1).getTime()-1}))
    .filter(item=>item.target>now.getTime()).sort((a,b)=>a.target-b.target).slice(0,2);
   const keys=upcoming.map(item=>item.name+"-"+item.target).join("|");
   if(keys!==activeHolidayKeys){
    activeHolidayKeys=keys;
    holidayCountdownSlots.forEach((nodes,index)=>{
     const holiday=upcoming[index];if(!holiday)return;
     nodes.emoji.textContent=holiday.emoji;
     nodes.name.textContent=holiday.name.toUpperCase();
     nodes.date.textContent=new Intl.DateTimeFormat(undefined,{weekday:"short",month:"short",day:"numeric",year:"numeric"}).format(holiday.date);
    });
   }
   holidayCountdownSlots.forEach((nodes,index)=>{
    const holiday=upcoming[index];if(!holiday)return;
    const totalSeconds=Math.max(0,Math.floor((holiday.target-now.getTime())/1000));
    const values={days:Math.floor(totalSeconds/86400),hours:Math.floor(totalSeconds%86400/3600),minutes:Math.floor(totalSeconds%3600/60),seconds:totalSeconds%60};
    Object.entries(values).forEach(([unit,value])=>{nodes[unit].textContent=String(value).padStart(2,"0")});
   });
  };
  updateUpcomingHolidays();window.setInterval(updateUpcomingHolidays,1000);
 }
