 const renderMemberRankings=async()=>{
  content.innerHTML='<section class="member-rankings-panel"><div class="account-section-head"><div><span class="eyebrow">CROWRULES CHARTS & RECOGNITION</span><h2>My Rankings</h2><p>Track your shows, host profile and listener achievements across the network.</p></div><label class="member-ranking-period-label">Chart period<select id="memberRankingPeriod"><option value="weekly">This week</option><option value="monthly">This month</option><option value="all_time">All time</option></select></label></div><div id="memberRankingSummary" class="member-ranking-summary"><div class="loading">Loading your ranking positions…</div></div><section class="member-ranking-history"><div class="account-section-head"><div><span class="eyebrow">YOUR CHART JOURNEY</span><h3>Ranking history</h3><p>Past chart positions captured by CrowRules.</p></div></div><div id="memberRankingHistory" class="member-ranking-history-list"><div class="loading">Loading chart history…</div></div></section><section class="member-ranking-awards"><div class="account-section-head"><div><span class="eyebrow">RECOGNITION EARNED</span><h3>Your achievements & badges</h3><p>Recognition assigned to your CrowRules member profile.</p></div><a class="btn secondary" href="'+SITE_BASE+'badges.html">Badge directory</a></div><div id="memberRankingBadges" class="member-ranking-badges"></div></section></section>';
  const periodSelect=$("#memberRankingPeriod"),summary=$("#memberRankingSummary"),historyRoot=$("#memberRankingHistory"),badgesRoot=$("#memberRankingBadges");
  const load=async()=>{
   const period=periodSelect.value,dbPeriod=period==="weekly"?"7_days":period==="monthly"?"30_days":"all_time";
   summary.innerHTML='<div class="loading">Refreshing your standings…</div>';
   try{
    const showIds=owned.map(x=>x.id),queries=[];
    if(showIds.length)queries.push(sb.from("podcast_rankings_period_live").select("podcast_id,podcast_title,ranking,ranking_score,listens,followers,previous_rank,movement_label").eq("period_type",dbPeriod).in("podcast_id",showIds).order("ranking",{ascending:true}));
    else queries.push(Promise.resolve({data:[],error:null}));
    if(creator?.id)queries.push(sb.from("host_rankings_period_live").select("host_key,host_name,ranking,ranking_score,listens,followers,previous_rank,movement_label").eq("period_type",dbPeriod).eq("host_key",creator.id).maybeSingle());
    else queries.push(Promise.resolve({data:null,error:null}));
    queries.push(sb.rpc("get_public_podcast_listener_play_leaderboard"));
    const [showResult,hostResult,listenerResult]=await Promise.all(queries);
    for(const result of [showResult,hostResult,listenerResult])if(result.error)throw result.error;
    const showRanks=showResult.data||[],hostRank=hostResult.data||null,listenerRows=listenerResult.data||[];
    const listenerIndex=listenerRows.findIndex(row=>row.user_id===u.id),listenerRank=listenerIndex>=0?{rank:listenerIndex+1,plays:Number(listenerRows[listenerIndex].qualified_plays||0),episodes:Number(listenerRows[listenerIndex].unique_episodes||0)}:null;
    const rankCard=(title,rank,detail,href,metric)=>{
     const position=Number(rank||0),progress=position>0?position<=10?100:Math.max(0,Math.min(99,Math.round(10/position*100))):0;
     return '<article class="member-rank-card"><div class="member-rank-card-top"><span class="eyebrow">'+esc(title)+'</span><strong>'+(position?'#'+position:'—')+'</strong></div><p>'+esc(detail)+'</p><div class="member-rank-progress"><span style="width:'+progress+'%"></span></div><div class="member-rank-card-foot"><small>'+(position<=10&&position>0?'<b class="member-rank-top10">TOP 10</b>':position?'Progress toward Top 10':'Not ranked yet')+'</small><small>'+esc(metric||"")+'</small></div>'+(href?'<a href="'+href+'">View chart ↗</a>':'')+'</article>';
    };
    let cards='';
    if(hostRank)cards+=rankCard("HOST STANDING",hostRank.ranking,"Your host profile · "+Number(hostRank.podcast_count||0)+" shows","rankings.html",""+Number(hostRank.listens||0).toLocaleString()+" listens");
    else if(creator)cards+=rankCard("HOST STANDING",0,"Your host profile is not ranked in this period.","rankings.html","");
    else cards+=rankCard("HOST STANDING",0,"Connect a host profile to appear in host rankings.","creator.html","");
    if(showRanks.length)showRanks.forEach(row=>cards+=rankCard("SHOW · "+(row.podcast_title||"YOUR SHOW"),row.ranking,"Your published show","show.html?id="+encodeURIComponent(row.podcast_id),Number(row.listens||0).toLocaleString()+" listens"));
    else cards+=rankCard("SHOW STANDING",0,owned.length?"Your shows are not ranked in this period yet.":"Publish a show to start building your chart position.","creator.html","");
    cards+=rankCard("LISTENER STANDING",listenerRank?.rank||0,listenerRank?"Based on your qualified plays. All-time public listener chart.":"Your listener profile is not currently listed. Check your public profile visibility settings.","rankings.html",listenerRank?listenerRank.plays.toLocaleString()+" qualified plays · "+listenerRank.episodes+" episodes":"Not on the public listener chart");
    summary.innerHTML=cards;
    const historyIds=[...new Set([...showIds,...(creator?.id?[creator.id]:[]),u.id])];
    if(historyIds.length){
     const{data:historyRows,error:historyError}=await sb.from("podcast_ranking_chart_history").select("ranking_type,period_type,entity_type,entity_id,rank,metric_count,captured_at").in("entity_id",historyIds).eq("period_type",dbPeriod).order("captured_at",{ascending:false}).limit(40);
     if(historyError)throw historyError;
     historyRoot.innerHTML=historyRows?.length?'<div class="member-ranking-history-table"><div class="member-ranking-history-head"><span>CHART</span><span>POSITION</span><span>METRIC</span><span>CAPTURED</span></div>'+historyRows.map(row=>'<div class="member-ranking-history-row"><span>'+esc(({podcasts:"Shows",hosts:"Hosts",listeners:"Listeners",episodes:"Episodes"})[row.ranking_type]||row.ranking_type)+'</span><b>#'+Number(row.rank)+'</b><span>'+Number(row.metric_count||0).toLocaleString()+'</span><time>'+new Date(row.captured_at).toLocaleDateString()+'</time></div>').join("")+'</div>':'<div class="account-empty"><h3>Your chart history is getting started.</h3><p>Once ranking snapshots are captured by CrowRules, your previous positions will appear here.</p><a class="btn secondary" href="'+SITE_BASE+'rankings.html">Explore current rankings</a></div>';
    }
   }catch(error){summary.innerHTML='<div class="notice">Your ranking profile could not be loaded: '+esc(error.message||"Please try again.")+'</div>';historyRoot.innerHTML='<div class="muted">Ranking history is temporarily unavailable.</div>'}
  };
  badgesRoot.innerHTML=visibleProfileBadges.length?'<div class="member-ranking-badge-grid">'+visibleProfileBadges.map(x=>'<article class="member-ranking-badge">'+(x.badge.image_url?'<img src="'+esc(x.badge.image_url)+'" alt="">':'<span>'+esc(x.badge.icon||"🏅")+'</span>')+'<div><b>'+esc(x.badge.name)+'</b><small>'+esc(x.badge.category||"Recognition")+'</small></div></article>').join("")+'</div>':'<div class="account-empty"><h3>Your recognition collection starts here.</h3><p>Profile badges awarded by CrowRules will appear here.</p><a class="btn secondary" href="'+SITE_BASE+'badges.html">Explore badges</a></div>';
  periodSelect.addEventListener("change",load);await load();
 };
