const preview=yt?'<div class="ce-media-frame"><iframe src="https://www.youtube-nocookie.com/embed/'+escCE(yt)+'" title="'+escCE(r.episode_title)+'" loading="lazy" allow="accelerometer; autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe></div>':media==="audio"?'<div class="ce-audio-player"><audio controls preload="none" src="'+escCE(r.episode_url)+'"></audio></div>':media==="video"?'<div class="ce-media-frame"><video controls preload="metadata" src="'+escCE(r.episode_url)+'"></video></div>':'<a class="btn secondary" href="'+escCE(r.episode_url)+'" target="_blank" rel="noopener noreferrer">Open submitted media ↗</a>';
