   const monthInput=$("#crReviewAnalyticsMonth"),status=$("#crReviewAnalyticsStatus"),pillars=$("#crReviewAnalyticsPillars"),engagement=$("#crReviewAnalyticsEngagement"),trends=$("#crReviewAnalyticsTrends"),satisfaction=$("#crReviewAnalyticsSatisfaction"),creators=$("#crReviewAnalyticsCreators"),report=$("#crReviewAnalyticsReport"),episodeInsights=$("#crReviewAnalyticsEpisodes");
   const now=new Date();monthInput.value=now.getFullYear()+"-"+String(now.getMonth()+1).padStart(2,"0");monthInput.max=monthInput.value;const minMonth=new Date(now.getFullYear(),now.getMonth()-11,1);monthInput.min=minMonth.getFullYear()+"-"+String(minMonth.getMonth()+1).padStart(2,"0");
   let snapshot=null;
